WHERE user_id = #{userId}
  AND model_name = 'STANDARD'
  AND usage_date = #{usageDate}
LIMIT 1

mapper.update:
UPDATE t_user_daily_usage
SET chat_count_used = chat_count_used + 1,
    last_chat_time = #{lastChatTime}
WHERE user_id = #{userId}
  AND model_name = 'STANDARD'
  AND usage_date = #{usageDate}

