SELECT 
FROM t_user_daily_usage
WHERE user_id = #{userId}
  AND model_name = #{modelName}
  AND usage_date >= DATE_SUB(CURDATE(), INTERVAL #{days} DAY)
ORDER BY usage_date DESC, model_name ASC
